<?php

declare(strict_types=1);

namespace AIC\Component\Application\Templates;

use AIC\Component\Application\ComponentTemplates;
use AIC\Component\Application\RenderPass;
use AIC\Component\Contracts\Component;
use AIC\Component\Domain\Button;
use AIC\Component\Domain\Checkbox;
use AIC\Component\Domain\FileInput;
use AIC\Component\Domain\HiddenInput;
use AIC\Component\Exception\UnknownComponent;
use Override;

/**
 * Generated by composer run build from framework/templates/components (#92): the template lookup (#98).
 * Do not edit; change the manifest and run composer run build.
 */
final readonly class AtomTemplatesPart3 implements ComponentTemplates
{
    /**
     * @param ComponentTemplates $componentTemplates The templates after these.
     */
    public function __construct(
        private ComponentTemplates $componentTemplates = new AtomTemplatesPart4(),
    ) {
    }

    /**
     * @param Component  $component  A component.
     * @param RenderPass $renderPass The pass rendering it.
     *
     * @throws UnknownComponent When no template renders it.
     *
     * @return string Its markup: the declared library atoms.
     */
    #[Override]
    public function compose(Component $component, RenderPass $renderPass): string
    {
        return match (true) {
            $component instanceof Checkbox => (new CheckboxTemplate())->render($component),
            $component instanceof FileInput => (new FileInputTemplate())->render($component),
            $component instanceof HiddenInput => (new HiddenInputTemplate())->render($component),
            $component instanceof Button => (new ButtonTemplate())->render($component),
            default => $this->componentTemplates->compose($component, $renderPass),
        };
    }
}
